{
    TypeInfoResolver = MyContext.Default
};

// 1) Strongly-typed retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T> directly
JsonTypeInfo<WeatherForecast> typedInfo = options.GetTypeInfo<WeatherForecast>();
Console.WriteLine($"Got JsonTypeInfo<WeatherForecast>  –  Type = {typedInfo.Type.Name}");

var forecast = new WeatherForecast("Seattle", 18);
string json = JsonSerializer.Serialize(forecast, typedInfo);
Console.WriteLine($"Serialized: {json}");

// 2) Probe without throwing: TryGetTypeInfo gives back a bool + non-generic info
bool found = options.TryGetTypeInfo(typeof(WeatherForecast), out JsonTypeInfo? info);
Console.WriteLine($"\nTryGetTypeInfo(WeatherForecast) → found={found}, type={info?.Type.Name}");

bool missing = options.TryGetTypeInfo(typeof(string), out JsonTypeInfo? info2);
Console.WriteLine($"TryGetTypeInfo(string)           → found={missing}, info={info2?.Type.Name ?? "(null)"}");

